#pragma once
#include "WaveIO.hpp"
inline int sampleTests(const Json& original,const std::string& file){
    int failures=0;auto check=[&](bool value,const char* name){std::printf("%s %s\n",value?"PASS":"FAIL",name);if(!value)++failures;};
    std::string error;auto decoded=loadSample(file,error);check(decoded&&decoded->frames()>SR,"WAV decoded and resampled to stereo 48k");
    auto data=std::make_shared<SampleData>();data->file="fixture.wav";data->stereo.resize(SR*2);for(int i=0;i<SR;++i){data->stereo[i*2]=static_cast<float>(std::sin(2*PI*330*i/SR)*.5);data->stereo[i*2+1]=static_cast<float>(std::sin(2*PI*550*i/SR)*.25);}
    Json base=original;for(auto& pattern:base["patterns"])for(auto& track:pattern){for(auto& step:track["steps"])step["on"]=false;track["mute"]=false;track["solo"]=false;for(auto& lfo:track["mod"]["lfos"])lfo["enabled"]=false;track["mod"]["arp"]["enabled"]=false;}
    for(auto& fx:base["trackFx"])for(auto& section:fx.items())section.value()["enabled"]=false;for(auto& section:base["fx"].items())section.value()["enabled"]=false;
    base["pattern"]=0;base["playMode"]="pattern";auto& track=base["patterns"][0][0];track["attack"]=.002;track["cutoff"]=18000;track["nativeSample"]={{"file",data->file},{"enabled",true},{"start",.1},{"end",.6},{"root",60},{"mode","one-shot"},{"gain",1.}};track["steps"][0]["note"]=60;track["steps"][0]["gate"]=0;
    check(validProject(base),"sample settings remain valid project data");std::ofstream("sample-roundtrip-check.json")<<base.dump(2);
    auto render=[](AudioEngine& e,int frames){std::array<int16_t,512> block{};double energy=0;for(int i=0;i<frames;i+=256){const int count=std::min(256,frames-i);e.render(block.data(),count);for(int n=0;n<count*2;++n)energy+=static_cast<double>(block[n])*block[n];}return energy;};
    {auto engine=std::make_unique<AudioEngine>(base);engine->samples[data->file]=data;engine->preview(0,0);const auto energy=render(*engine,SR/10);check(energy>0&&std::abs(engine->samplePosition(0)-.2)<.001,"sample playback / stereo audio / region start");render(*engine,SR/2);check(engine->samplePosition(0)<0,"one shot stops at region end");}
    {auto p=base;p["patterns"][0][0]["steps"][0]["note"]=72;auto engine=std::make_unique<AudioEngine>(p);engine->samples[data->file]=data;engine->preview(0,0);render(*engine,SR/10);check(std::abs(engine->samplePosition(0)-.3)<.001,"one octave doubles sample playback speed");}
    {auto p=base;p["patterns"][0][0]["nativeSample"]["mode"]="reverse-loop";p["patterns"][0][0]["steps"][0]["gate"]=400;auto engine=std::make_unique<AudioEngine>(p);engine->samples[data->file]=data;engine->preview(0,0);render(*engine,SR/10);check(std::abs(engine->samplePosition(0)-.5)<.001,"reverse begins at region end");render(*engine,SR/2);check(std::abs(engine->samplePosition(0)-.5)<.001,"reverse loop wraps within selected region");}
    {auto p=base;auto& lfo=p["patterns"][0][0]["mod"]["lfos"][0];lfo["enabled"]=true;lfo["routes"]=Json::array({{{"target","pitch"},{"from",12},{"to",12}}});auto engine=std::make_unique<AudioEngine>(p);engine->samples[data->file]=data;engine->preview(0,0);render(*engine,SR/10);check(std::abs(engine->samplePosition(0)-.3)<.001,"existing LFO pitch changes sample rate");}
    {auto p=base;p["patterns"][0][0]["steps"][0]["on"]=true;auto engine=std::make_unique<AudioEngine>(p);engine->samples[data->file]=data;engine->start();check(render(*engine,SR/10)>0&&engine->triggers==1,"sequencer triggers WAV");}
    {auto engine=std::make_unique<AudioEngine>(base);engine->preview(0,0);check(render(*engine,SR/10)==0,"missing sample stays silent");}
    {auto p=base;auto& t=p["patterns"][0][0];t["nativeSample"]["slices"]=4;t["steps"][0]["slice"]=3;auto engine=std::make_unique<AudioEngine>(p);engine->samples[data->file]=data;engine->preview(0,0);render(*engine,SR/20);check(std::abs(engine->samplePosition(0)-.4)<.001,"step selects slice 3 within trimmed region");render(*engine,SR/10);check(engine->samplePosition(0)<0,"slice stops at its own end");}
    {auto p=base;auto& t=p["patterns"][0][0];t["nativeSample"]["slices"]=4;t["nativeSample"]["mode"]="reverse";t["steps"][0]["slice"]=3;auto engine=std::make_unique<AudioEngine>(p);engine->samples[data->file]=data;engine->preview(0,0);render(*engine,SR/20);check(std::abs(engine->samplePosition(0)-.425)<.001,"reverse playback stays inside selected slice");}
    {auto p=base;auto& t=p["patterns"][0][0];t["nativeSample"]["slices"]=4;t["steps"][0]["slice"]=4;t["steps"][0]["on"]=true;auto engine=std::make_unique<AudioEngine>(p);engine->samples[data->file]=data;engine->start();render(*engine,SR/20);check(std::abs(engine->samplePosition(0)-.525)<.001&&engine->triggers==1,"sequencer carries slice assignment into event");check(validProject(p),"slice project validation");std::ofstream("sample-roundtrip-check.json")<<p.dump(2);}
    {auto low=base,high=base;low["patterns"][0][0]["nativeSample"]["gain"]=.5;auto a=std::make_unique<AudioEngine>(low),b=std::make_unique<AudioEngine>(high);a->samples[data->file]=data;b->samples[data->file]=data;a->preview(0,0);b->preview(0,0);const auto quieter=render(*a,SR/10),louder=render(*b,SR/10);check(louder>quieter*3.5,"sample gain changes audible energy by six dB");}
    {auto p=base;p["bpm"]=120;auto& t=p["patterns"][0][0];t["nativeSample"].update({{"slices",4},{"walk","active"}});t["steps"][0].update({{"on",true},{"slice",2}});auto e=std::make_unique<AudioEngine>(p);e->samples[data->file]=data;e->start();render(*e,256);const int first=e->lastSlices[0];render(*e,SR*4);const int second=e->lastSlices[0];const double expected=.1+(second-1)*.125+256./SR;check(first==2&&second!=first&&second>=1&&second<=4&&std::abs(e->samplePosition(0)-expected)<.001,"walk changes actual sample region without rewriting step");check(get(e->project["patterns"][0][0]["steps"][0],"slice")==2,"walk preserves programmed slice anchor");}
    {auto p=base;p["bpm"]=120;auto& t=p["patterns"][0][0];t["nativeSample"].update({{"slices",4},{"walk","active"}});t["steps"][0].update({{"on",true},{"slice",2},{"condition","2/2"}});auto e=std::make_unique<AudioEngine>(p);e->samples[data->file]=data;e->start();render(*e,SR*4);const bool skipped=e->lastSlices[0]==0&&e->triggers==0;render(*e,256);check(skipped&&e->lastSlices[0]==2&&e->triggers==1,"condition skips do not advance walk");}
    const std::string output="samples/.loopfield-test-"+std::to_string(SDL_GetTicks())+".wav";auto settings=track["nativeSample"];settings["mode"]="reverse";const bool saved=exportSampleRegion(*data,settings,output);auto region=saved?loadSample(output.substr(8),error):nullptr;
    check(region&&region->frames()==SR/2&&std::abs(region->stereo[0]-data->stereo[(static_cast<int>(SR*.6)-1)*2])<.0001,"non-destructive reverse region WAV export");if(saved)std::remove(output.c_str());
    std::printf("SAMPLE_TEST failures=%d\n",failures);return failures?1:0;
}
